(()=>{'use strict';const ids=['svc-edge','svc-checkout','svc-payments','svc-paymentdb','svc-kubernetes','svc-azure','svc-dns','svc-provider','svc-publicdns'];let selected=null,current=null;
const $=id=>document.getElementById(id);const el=(tag,cls,text)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(text!==undefined)x.textContent=text;return x};
function paint(data){if(!data||data.domain!=='commerce')return;current=data;const root=$('payment-groups');root.replaceChildren();for(const id of ids){const service=data.service.find(x=>x.id===id);if(!service)continue;const members=data.network.filter(x=>x.parent===id||(x.otherParents||[]).includes(id));const card=el('article','payment-group'+(selected===id?' selected':''));const header=el('div','payment-group-head');header.append(el('span','',id==='svc-paymentdb'?'DATA / VMS':id==='svc-kubernetes'?'KUBERNETES':id==='svc-azure'?'AZURE / VMS':id==='svc-dns'?'DNS':id==='svc-payments'?'PAYMENT WORKLOADS':id==='svc-provider'?'PAYMENT PARTNER':id==='svc-publicdns'?'EXTERNAL DNS':'APPLICATION / EDGE'),el('small','',`${members.length} components`));card.append(header);const chips=el('div','payment-chips');members.forEach(m=>{const chip=el('span','payment-chip'+(m.status==='degraded'?' affected':''),m.label);chip.title=m.sub;chips.append(chip)});card.append(chips,el('div','payment-flow-arrow','↓'));const b=el('button','payment-service '+service.status,service.label);b.type='button';b.append(el('small','payment-service-state',service.status==='unknown'?'UNKNOWN':service.status.toUpperCase()));b.setAttribute('aria-pressed',String(selected===id));b.addEventListener('click',()=>{selected=id;paint(current)});card.append(b);root.append(card)}const cap=data.outcome.find(n=>n.id==='cap-payment');$('payment-cap-state').textContent=cap?.status==='degraded'?'DEGRADED':'HEALTHY';$('payment-cap-state').classList.toggle('affected',cap?.status==='degraded');$('payment-stage').textContent=['BASELINE','DNS PRESSURE','CHECKOUT AFFECTED','PAYMENT FAILURE','RECOVERY'][data.step];const service=data.service.find(s=>s.id===selected);$('payment-selection-title').textContent=service?`${service.label}: select “Inspect service” to see its relationships and components.`:'Select a service to trace it in the graph.';$('payment-inspect').disabled=!service;}
$('payment-inspect').addEventListener('click',()=>{if(!selected)return;if(document.querySelector('.atlas-domain[data-domain="commerce"]').getAttribute('aria-selected')!=='true')document.querySelector('.atlas-domain[data-domain="commerce"]').click();document.querySelector('.atlas-view[data-layer="service"]').click();const service=current?.service.find(x=>x.id===selected);if(service){const node=Array.from(document.querySelectorAll('#atlas-graph .atlas-node')).find(n=>n.getAttribute('aria-label')?.startsWith(service.label+','));if(node)node.dispatchEvent(new MouseEvent('click',{bubbles:true}));}document.getElementById('explorer').scrollIntoView({behavior:'smooth'})});
$('payment-incident').addEventListener('click',()=>{document.querySelector('.atlas-domain[data-domain="commerce"]').click();document.querySelectorAll('#atlas-step-track button')[3].click()});$('payment-reset').addEventListener('click',()=>{document.querySelector('.atlas-domain[data-domain="commerce"]').click()});window.addEventListener('atlas:changed',e=>paint(e.detail));paint(window.__paymentExampleData);
})();
